// Quality Gatekeeper — Role 10 per AI-TEAM-DISTRIBUTION. Pre-merge gate
// for any PR that touches a visible surface (PWA component, public
// endpoint, marketing copy, demo data). Runs the binding-foundation
// checks via Ollama 14b and returns a structured pass/fail with
// rationale.
//
// Per SYSTEM-SKILLS-INVENTORY skill F.8 Testing Discipline.
// Per BUSINESS-PROCESS-CONNECTIONS five-question test for visible
// surfaces. Per typographic theology rules in CLAUDE.md.
//
// POST body shape:
//   { pr_number?, pr_title, diff_text, files_changed: [{path, ...}],
//     touches_visible_surface?: boolean }
//
// Returns:
//   { ok, pass: boolean, checks: { foundation_screen, typographic_theology,
//     excellence_standard, business_process_connections, scripture_citation },
//     rationale, must_fix?: [...], suggestions?: [...] }

const OLLAMA_BASE = process.env.OLLAMA_BASE_URL || 'http://ollama:11434';
const OLLAMA_MODEL = process.env.OLLAMA_GATEKEEPER_MODEL || 'qwen2.5:14b-instruct-q4_K_M';

const input = $input.first().json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

const prTitle = (body.pr_title || '').toString();
const diffText = (body.diff_text || '').toString();
const filesChanged = Array.isArray(body.files_changed) ? body.files_changed : [];
const touchesVisible = body.touches_visible_surface === true || filesChanged.some(f => /\.(jsx|tsx|html|md)$/i.test((f && f.path) || ''));

if (!diffText) {
  return [{ json: { ok: false, error: 'diff_text is required' } }];
}

// Deterministic checks first — these don't need an LLM.
function checkTypographicTheology(text) {
  // Per CLAUDE.md: lucifer/satan/devil/dragon/adversary/accuser/deceiver
  // are NEVER capitalized. Yahweh/Jesus/Holy Spirit/Father/Son ALWAYS
  // capitalized as proper names; pronouns (He/His/Him/Himself) capitalized
  // when referring to God.
  const violations = [];
  // Adversary names that should never be capitalized at start of word.
  const adversaryRe = /\b(Lucifer|Satan|Devil|Dragon|Adversary|Accuser|Deceiver)\b/g;
  const advMatches = text.match(adversaryRe);
  if (advMatches) violations.push('adversary names capitalized: ' + Array.from(new Set(advMatches)).join(', '));
  // God-name lowercase violations (lowercase 'yahweh', 'jesus', 'holy spirit' in narrative text)
  // Only flag in NEW content (added lines starting with +).
  const addedLines = text.split('\n').filter(l => l.startsWith('+') && !l.startsWith('+++'));
  const addedText = addedLines.join('\n');
  const godLowerRe = /\b(yahweh|jesus christ|holy spirit)\b/g;
  const godMatches = addedText.match(godLowerRe);
  if (godMatches) violations.push('God-name not capitalized in added text: ' + Array.from(new Set(godMatches)).join(', '));
  return { pass: violations.length === 0, violations };
}

const typographicTheology = checkTypographicTheology(diffText);

// Light foundation principle checks via Ollama 14b.
const prompt = `You are the Quality Gatekeeper for the PoeTech Family OS. You review PR diffs against the project's binding foundation principles before merge.

Principles to check (these come from foundation docs - judge the diff against each):

1. FOUNDATION-SCREEN — Does the change respect the project's foundation docs? Look for changes to demo data, marketing copy, public surfaces, or principle docs themselves.

2. TYPOGRAPHIC-THEOLOGY — Yahweh/Jesus/Holy Spirit/Father/Son ALWAYS capitalized; lucifer/satan/devil/adversary/accuser/deceiver NEVER capitalized.

3. EXCELLENCE-STANDARD — Religion AND relationship. Does new copy have backbone (scripture-grounded, structurally sound) AND warmth (meets reader where they are)? Cold legalism fails. Sentimental drift fails.

4. BUSINESS-PROCESS-CONNECTIONS — For any new visible surface, does the diff demonstrate awareness of the five questions: invites / pipeline / governor / promise / timeline?

5. SCRIPTURE-CITATION (only if scripture appears) — ESV primary, KJV secondary. Pattern: **ESV - Book Chapter:Verse:** *"text"*. No improvised translations.

For each principle, judge PASS / FAIL / NOT_APPLICABLE.

Return ONLY a JSON object with this exact shape:

{
  "foundation_screen": "pass" | "fail" | "not_applicable",
  "excellence_standard": "pass" | "fail" | "not_applicable",
  "business_process_connections": "pass" | "fail" | "not_applicable",
  "scripture_citation": "pass" | "fail" | "not_applicable",
  "rationale": "2-3 sentences explaining the call. Specific. No filler.",
  "must_fix": ["any specific items that must change before merge"],
  "suggestions": ["any optional improvements"]
}

PR title: ${prTitle}
Touches visible surface: ${touchesVisible}
Files changed: ${filesChanged.map(f => (f && f.path) || '').join(', ')}

Diff (truncated to first 8000 chars):
${diffText.slice(0, 8000)}

Return ONLY the JSON. No preamble, no markdown.`;

let checks = null;
let rawResponse = '';
try {
  const r = await fetch(OLLAMA_BASE + '/api/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: OLLAMA_MODEL, prompt, stream: false, options: { temperature: 0.2, num_predict: 1200 } }),
    signal: AbortSignal.timeout(180000)
  });
  const data = await r.json();
  rawResponse = (data.response || '').trim();
  const m = rawResponse.match(/\{[\s\S]*\}/);
  if (m) { try { checks = JSON.parse(m[0]); } catch (_) {} }
} catch (e) {
  return [{ json: { ok: false, error: 'gatekeeper LLM call failed: ' + String(e), typographic_theology: typographicTheology } }];
}

if (!checks) {
  return [{ json: { ok: false, error: 'could not parse gatekeeper output', raw: rawResponse.slice(0, 2000), typographic_theology: typographicTheology } }];
}

// Combine deterministic + LLM checks. Any 'fail' anywhere = overall fail.
const allChecks = {
  foundation_screen: checks.foundation_screen || 'not_applicable',
  typographic_theology: typographicTheology.pass ? 'pass' : 'fail',
  excellence_standard: checks.excellence_standard || 'not_applicable',
  business_process_connections: checks.business_process_connections || 'not_applicable',
  scripture_citation: checks.scripture_citation || 'not_applicable'
};

const anyFail = Object.values(allChecks).some(v => v === 'fail');
const rationale = checks.rationale || '';
const must_fix = Array.isArray(checks.must_fix) ? checks.must_fix.slice() : [];
if (typographicTheology.violations.length) {
  must_fix.push('Typographic theology: ' + typographicTheology.violations.join('; '));
}

return [{ json: { ok: true, pass: !anyFail, checks: allChecks, rationale, must_fix, suggestions: checks.suggestions || [] } }];
